WITH parsed AS (SELECT id, status_code, payload_json, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['version'] AS version FROM app_logs) SELECT CASE WHEN status_code >= 458 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, PERCENTILE_APPROX(status_code, 0.95) AS status_code_p95, APPROX_PERCENTILE(status_code, 0.9) AS status_code_p90, APPROX_PERCENTILE(status_code, 0.9) AS status_code_p90_2 FROM parsed GROUP BY status_code_tier HAVING status_code_p95 > 0 ORDER BY status_code_p90 DESC NULLS LAST
